import { setTimeout as sleep } from "node:timers/promises";
import { closeDb } from "../db";
import { expireVideoUploads } from "../lib/video-upload-sessions";
import { runStorageCleanupBatch } from "../lib/storage-cleanup";

const controller = new AbortController();
for (const signal of ["SIGTERM", "SIGINT"] as const) process.on(signal, () => controller.abort());
const once = process.argv.includes("--once");
const poll = Number(process.env.STORAGE_CLEANUP_POLL_MS || 10_000);
try {
  if (!Number.isSafeInteger(poll) || poll < 1000 || poll > 60_000) throw new Error("Invalid cleanup poll interval");
  let consecutiveFailures = 0;
  do {
    try {
      await expireVideoUploads();
      const result = await runStorageCleanupBatch({ signal: controller.signal });
      consecutiveFailures = 0;
      if (result.processed || result.failed) console.info(JSON.stringify({ event: "storage.cleanup.batch", processed: result.processed, failed: result.failed }));
    } catch {
      if (controller.signal.aborted) break;
      // Required worker failure is visible to the runtime supervisor.
      if (once || ++consecutiveFailures >= 3) throw new Error("Cleanup database unavailable");
    }
    if (!once) await sleep(poll, undefined, { signal: controller.signal }).catch(() => undefined);
  } while (!once && !controller.signal.aborted);
} catch {
  console.error("[storage-cleanup-worker] Required cleanup service failed");
  process.exitCode = 1;
} finally { await closeDb().catch(() => undefined); }

import assert from "node:assert/strict";
/** Isolate only the persistent queue/transport boundary in legacy deletion tests.
 * Real transaction, crash recovery and worker claiming are tested on PostgreSQL. */
export function cleanupFixture(database, remove) {
  const jobs = new Map();
  return {
    async retireOwnerVideoUploadsTx() { assert.equal(database.inTransaction(), true); },
    async enqueueStorageCleanupTx(_tx, targets) {
      assert.equal(database.inTransaction(), true, "cleanup intent must be inside the owning transaction");
      return [...new Map(targets.map(target => [JSON.stringify([target.provider, target.recursive, target.key]), target])).values()]
        .map(target => { const row = { ...target, id: crypto.randomUUID(), provider: target.provider ?? "local" }; jobs.set(row.id, row); return row; });
    },
    async runStorageCleanupBatch({ ids }) {
      assert.equal(database.inTransaction(), false); assert.equal(database.committed(), true);
      const failures = [];
      await Promise.all(ids.map(async id => {
        const job = jobs.get(id); assert.ok(job, "only transactionally queued work may execute");
        try { await remove(job.recursive ? "prefix" : "object", job.key, job.provider); }
        catch { failures.push(`${job.source}:${job.key}`); }
      }));
      return { processed: ids.length - failures.length, failed: failures.length, failures };
    },
  };
}
